#!/bin/sh
set -eu
# Secrets generated by init-local.ps1 are hexadecimal; reject SQL metacharacters.
for value in "$M1_DB_PASSWORD" "$M2_DB_PASSWORD" "$M3_DB_PASSWORD"; do
  case "$value" in ''|*[!a-fA-F0-9]*) echo 'Database passwords must be hexadecimal' >&2; exit 1;; esac
done
MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql -uroot <<SQL
CREATE DATABASE IF NOT EXISTS campus_m1 CHARACTER SET utf8mb4;
CREATE DATABASE IF NOT EXISTS campus_m2 CHARACTER SET utf8mb4;
CREATE DATABASE IF NOT EXISTS campus_m3 CHARACTER SET utf8mb4;
CREATE USER IF NOT EXISTS 'm1'@'%' IDENTIFIED BY '$M1_DB_PASSWORD';
CREATE USER IF NOT EXISTS 'm2'@'%' IDENTIFIED BY '$M2_DB_PASSWORD';
CREATE USER IF NOT EXISTS 'm3'@'%' IDENTIFIED BY '$M3_DB_PASSWORD';
GRANT ALL ON campus_m1.* TO 'm1'@'%';
GRANT ALL ON campus_m2.* TO 'm2'@'%';
GRANT ALL ON campus_m3.* TO 'm3'@'%';
SQL
